import{_ as a,C as n,o as r,c as i,a2 as t,E as s}from"./chunks/framework.9yf7n3zg.js";const d="/guide/media/find-open.webp",h="/guide/media/find-make-row.webp",l="/guide/media/find-meaning.webp",g="/guide/media/find-meaning-offer.webp",c="/guide/media/find-hotkeys.webp",T=JSON.parse('{"title":"Find, open and make","description":"","frontmatter":{},"headers":[],"relativePath":"guide/find.md","filePath":"guide/find.md","lastUpdated":1791677002000}'),p={name:"guide/find.md"};function m(w,e,u,f,y,k){const o=n("Clip");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="find-open-and-make" tabindex="-1">Find, open and make <a class="header-anchor" href="#find-open-and-make" aria-label="Permalink to &quot;Find, open and make&quot;">​</a></h1><p>Leathercase has one field for finding things and making them: the find field in the middle of the title bar. Type a few letters and it lists the stories, views, commands, cards, tags, notes and, inside a story, its people, places and scenes. Type a word and a colon, <code>character: Inés Roca</code>, and it makes one. This page covers that field, the search inside a view, the search of your stories&#39; text, and the capture window that takes a line from any app.</p><p><img src="'+d+'" alt="The find field open under the title bar, listing Recent, Stories and the commands" width="1130" height="720" loading="lazy"></p><h2 id="open-the-field" tabindex="-1">Open the field <a class="header-anchor" href="#open-the-field" aria-label="Permalink to &quot;Open the field&quot;">​</a></h2><p>There are three ways in, and they all put the caret in the same field:</p><table tabindex="0"><thead><tr><th>Do this</th><th>What happens</th></tr></thead><tbody><tr><td>Click the field in the title bar</td><td>The list drops under it</td></tr><tr><td><code>Ctrl+K</code> (Cmd+K on macOS)</td><td>Opens the field, or closes it if it is open. The key is shown in the field while it is closed</td></tr><tr><td><code>Ctrl+O</code></td><td><strong>Find or make in this view</strong>: opens the field from any view</td></tr></tbody></table><p>The field reads <strong>Find anything, or make it: character: Nora</strong> until you type. While it is open:</p><ul><li><code>↑</code> and <code>↓</code> move through the list.</li><li><code>Enter</code> runs the row in hand.</li><li><code>Esc</code>, or a click anywhere else, closes the field. Esc closes only the field; it does not take you back a screen.</li></ul><p>The line at the foot of the list repeats these keys: <strong>↑ ↓ move</strong>, <strong>enter run</strong>, <strong>esc close</strong> and <strong>word: title makes it</strong>.</p><h2 id="what-the-empty-field-shows" tabindex="-1">What the empty field shows <a class="header-anchor" href="#what-the-empty-field-shows" aria-label="Permalink to &quot;What the empty field shows&quot;">​</a></h2><p>With nothing typed, the list is a map of the app:</p><ul><li><strong>Recent</strong>: the commands you ran last.</li><li><strong>Stories</strong>: every story of the home, each with a word on where it stands (<strong>on pace</strong>, <strong>behind</strong>, <strong>no target</strong>, <strong>not read yet</strong> and so on). Pick one to open it.</li><li><strong>Go</strong>, <strong>Story</strong>, <strong>View</strong> and <strong>App</strong>: every command the app has, grouped, each with its key. <strong>Go</strong> holds the places and views (<strong>Library</strong>, <strong>Desk</strong>, <strong>Writer</strong>, <strong>Tags</strong>, <strong>Plot grid</strong>, <strong>Graph</strong>, <strong>Manuscript</strong> and the rest); <strong>Story</strong> the commands on the open story, such as <strong>Export the manuscript as one file</strong> and <strong>Story settings</strong>; <strong>View</strong> the commands on the view on screen; <strong>App</strong> those on the app itself, such as <strong>Settings</strong> and the themes.</li></ul><p>A command that needs a story only shows when a story is open.</p><p>Under the list, the mate may add a line headed <strong>Not tried yet</strong>: one command you have not used, with <strong>Try it</strong> and <strong>Don&#39;t suggest this</strong>. On the sample home, and once you have hidden it, <strong>Start here</strong> is offered here too. Both work on this computer with no model.</p><h2 id="find-something" tabindex="-1">Find something <a class="header-anchor" href="#find-something" aria-label="Permalink to &quot;Find something&quot;">​</a></h2><p>Type and the list narrows as you go. Matching ignores case and accents, so <code>ines</code> finds Inés. Each section shows its first six matches:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it lists</th><th>What picking it does</th></tr></thead><tbody><tr><td><strong>Stories</strong></td><td>Stories whose name matches</td><td>Opens the story</td></tr><tr><td><strong>In this story</strong></td><td>The open story&#39;s characters, places, items, factions and events, with their kind</td><td>Opens the <a href="/guide/guide/graph">Graph</a> with that one pinned</td></tr><tr><td><strong>Scenes</strong></td><td>The open story&#39;s scenes by title, with the note they are in</td><td>Opens the <a href="/guide/guide/manuscript">Manuscript</a> at that scene: its heading at the top of the page and its first sentence selected</td></tr><tr><td><strong>Cards</strong></td><td>The Writer Board&#39;s cards, with their kind, or <strong>card</strong> or <strong>your note</strong></td><td>Opens the <a href="/guide/guide/writer-board">Writer Board</a> with the card selected</td></tr><tr><td><strong>Tags</strong></td><td>Every tag of the home, as <code>#tag</code></td><td>Opens the <a href="/guide/guide/tags">Tags</a> view with the tag selected</td></tr><tr><td><strong>Notes</strong></td><td>Every note of the home by its name, with the folder it sits in. A long folder is cut short and the name kept; rest the pointer on it to read it whole. The daily snapshots in <code>suite/daily/</code> are not listed</td><td>Opens the note in the program you write in. A card Leathercase made opens on the board instead</td></tr><tr><td><strong>Go</strong>, <strong>Story</strong>, <strong>View</strong>, <strong>App</strong></td><td>Commands whose name matches</td><td>Runs the command</td></tr></tbody></table><p><strong>In this story</strong> and <strong>Scenes</strong> appear only while a story is open. A name Leathercase found in the prose with no note of its own (a candidate) is not listed here; find it in the Graph.</p><p>When nothing matches, the list says <strong>Nothing matches. Esc closes.</strong></p>',19)),s(o,{name:"find-scene",caption:"Typing part of a scene's title and picking it opens the manuscript at that scene, its first sentence selected"}),e[1]||(e[1]=t('<h2 id="make-something-with-a-word-and-a-colon" tabindex="-1">Make something with a word and a colon <a class="header-anchor" href="#make-something-with-a-word-and-a-colon" aria-label="Permalink to &quot;Make something with a word and a colon&quot;">​</a></h2><p>A word, a colon and a title makes a thing. As soon as you type the first letters of a word, the section <strong>Make with a word</strong> offers the words that fit, each with what it makes: type <code>cha</code> and it offers <code>character:</code>. Picking a word puts it in the field, ready for the title.</p><p>Once there is a title after the colon, the first row of the list is <strong>Make</strong>, saying what it will make and where. Press Enter to make it.</p><p>A command whose name starts with a word and a colon is still found by its name. Type <code>Theme: light</code> in full and the command <strong>Theme: light</strong> comes first, above the <strong>Make</strong> row, so Enter runs it. Type less, <code>theme: li</code>, and <strong>Make</strong> comes first.</p><p><img src="'+h+'" alt="The find field with &quot;theme: What we owe&quot; typed, the Make row saying New card What we owe, in Themes, a theme" width="1130" height="180" loading="lazy"></p><h3 id="the-words" tabindex="-1">The words <a class="header-anchor" href="#the-words" aria-label="Permalink to &quot;The words&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Word</th><th>Outside a story</th><th>Inside a story</th></tr></thead><tbody><tr><td><code>character:</code></td><td>A card of the kind character on the Writer Board, in the list that takes characters (<strong>Archetypes</strong> on the default framework)</td><td>A character note for the story</td></tr><tr><td><code>place:</code></td><td>A card of the kind place (in <strong>Worlds</strong> by default)</td><td>A place note for the story</td></tr><tr><td><code>event:</code></td><td>A card of the kind event (in <strong>Plots</strong> by default)</td><td>An event note for the story</td></tr><tr><td><code>idea:</code>, <code>theme:</code>, <code>premise:</code>, <code>reference:</code> and every other kind the board has</td><td>A card of that kind, in the list for that kind</td><td>The same: a card on the board</td></tr><tr><td><code>tag:</code></td><td>A tag</td><td>A tag</td></tr><tr><td><code>note:</code></td><td>A card of no kind in <strong>Ideas</strong></td><td>A note for the story</td></tr><tr><td><code>card:</code></td><td>A card in <strong>Ideas</strong></td><td>A card in <strong>Ideas</strong></td></tr><tr><td><code>mark:</code></td><td>Not offered</td><td>A named mark in the story&#39;s <a href="/guide/guide/sentence-log">Sentence log</a></td></tr><tr><td>The name of a board list, <code>quotes:</code> or <code>smells:</code></td><td>A card in that list</td><td>A card in that list</td></tr></tbody></table><p>The kinds come from the Writer Board&#39;s framework, so a kind you add there (see <a href="/guide/guide/writer-board#kinds">Kinds</a>) becomes a word here. The words themselves are the field&#39;s grammar: they stay in English whatever language the app is in.</p><h3 id="where-a-made-thing-opens" tabindex="-1">Where a made thing opens <a class="header-anchor" href="#where-a-made-thing-opens" aria-label="Permalink to &quot;Where a made thing opens&quot;">​</a></h3><p>What you make opens where it belongs, with the caret in its text so you can write it straight away:</p><ul><li><strong>A card</strong> opens on the Writer Board, selected, its text in hand in the side column. It is a markdown note in the home&#39;s <code>Writer/</code> folder, tagged for its list. See <a href="/guide/guide/writer-board#cards-are-notes">Cards are notes</a>.</li><li><strong>A character, place, event or note for the story</strong> opens in the Graph, pinned, with its note open to write in. It is a note in the story&#39;s <code>suite/</code> folder: <code>suite/Characters/Inés Roca.md</code>, <code>suite/Places/…</code>, <code>suite/Events/…</code> or <code>suite/Notes/…</code>, typed in its front matter. If the story already has a note of yours for the same name, the Graph shows yours and Leathercase&#39;s note sits beside it as its companion. A title already taken gets a number, so no note is ever overwritten.</li><li><strong>A tag</strong> goes on the card in hand when you are on the Writer Board with one of Leathercase&#39;s cards selected. Otherwise it is entered in the home&#39;s <code>suite/Tags.md</code> and the Tags view opens with it selected.</li><li><strong>A mark</strong> is written into the story&#39;s sentence log. <strong>Mark the sentence log</strong> in the <strong>Story</strong> commands puts <code>mark: </code> in the field for you. While you name a mark, the list shows only the mark&#39;s row: nothing else is found.</li></ul><p>Nothing you make here is written into your own notes.</p>',12)),s(o,{name:"find-make-character",caption:"In a story, character: makes a note for the story and the Graph opens on it, ready to be written"}),e[2]||(e[2]=t('<h3 id="plain-text-makes-an-idea" tabindex="-1">Plain text makes an idea <a class="header-anchor" href="#plain-text-makes-an-idea" aria-label="Permalink to &quot;Plain text makes an idea&quot;">​</a></h3><p>Text with no word and colon finds, and also offers to make: the last row of the list is <strong>Make</strong>, <strong>New card</strong> with your text as its title, <strong>in Ideas, an idea</strong>. Enter on it makes the card and opens it on the board. The row is not offered when a card already has that title, so pressing Enter twice does not make two.</p><p>A question is never made into a card. Text ending in <code>?</code>, or starting with &quot;how do I&quot;, &quot;how to&quot; or &quot;how can I&quot;, gets the mate&#39;s answer instead (see below).</p><h2 id="ctrl-f-search-in-this-view" tabindex="-1">Ctrl+F: search in this view <a class="header-anchor" href="#ctrl-f-search-in-this-view" aria-label="Permalink to &quot;Ctrl+F: search in this view&quot;">​</a></h2><p><code>Ctrl+F</code> (<strong>Search in this view</strong>) goes to the search field of the view on screen, when the view has one:</p><table tabindex="0"><thead><tr><th>View</th><th>Its field</th></tr></thead><tbody><tr><td><a href="/guide/guide/graph">Graph</a></td><td><strong>Find a name</strong>, in the side column. If the column is folded, Ctrl+F opens it</td></tr><tr><td><a href="/guide/guide/characters">Characters</a></td><td><strong>Filter the cast</strong></td></tr><tr><td>Any other view</td><td>Ctrl+F opens the find field in the title bar</td></tr></tbody></table><h2 id="search-your-stories-text" tabindex="-1">Search your stories&#39; text <a class="header-anchor" href="#search-your-stories-text" aria-label="Permalink to &quot;Search your stories&#39; text&quot;">​</a></h2><p>Type three letters or more, with no colon and not a question, and the find field also searches the text of every story in the home. The passages appear under the list:</p><ul><li><strong>Words</strong>: passages that hold the words you typed, with the words marked, each with its story and scene and a <strong>words</strong> label. If none do, it says <strong>No passage has these words.</strong></li><li>Pick a passage and the story opens on it: the manuscript at that scene.</li></ul><p>Words match whole, so <code>went</code> never finds twenty. The last word is the one you are still typing, so it also matches by its beginning: <code>the lamp w</code> finds &quot;the lamp went out&quot;. A long word allows a slip of a letter. Passages that hold your words as you typed them, in that order, come first; passages that hold them apart follow.</p><p>The search reads what you wrote: the scenes of your stories and the sentences in their logs. It leaves out Leathercase&#39;s own files, the daily snapshots, and comments hidden in your notes, which are also taken out of the passage it shows.</p><p>While the search runs, the field says <strong>Searching the stories…</strong>. Word search is plain matching, done on this computer, and needs nothing installed.</p><p><img src="'+l+'" alt="The find field with &quot;the lamp went out&quot; typed: a note with its folder, the Make row, and the passages under Words, those holding the phrase first, the words marked" width="1130" height="877" loading="lazy"></p><h3 id="search-by-meaning" tabindex="-1">Search by meaning <a class="header-anchor" href="#search-by-meaning" aria-label="Permalink to &quot;Search by meaning&quot;">​</a></h3><p>Meaning search finds passages that say the same thing in other words, in any language your stories use: a search for &quot;the light failed&quot; may find a passage where the lamp went out. It needs a small model, downloaded once; after that it runs on this computer, and your text never leaves it.</p><p>Leathercase asks about it once, the first time a word search finds nothing. The box <strong>Search by meaning</strong>, <strong>not on this computer yet</strong>, gives the model&#39;s name, licence and size, with:</p><ul><li><strong>Download</strong> and the size, to fetch it. A bar shows <strong>Downloading the meaning model</strong>, with <strong>Pause</strong>, <strong>Resume</strong> and <strong>Cancel</strong>. Then <strong>Then it reads your stories once</strong>, with a count of stories. Word search works meanwhile.</li><li><strong>Not now</strong>, which keeps word search and does not ask again for a week.</li></ul><p><img src="'+g+'" alt="A search that finds no passage: No passage has these words, and the box Search by meaning, not on this computer yet, with Download and Not now" width="1130" height="499" loading="lazy"></p><p>If a download does not finish, the box says why and offers <strong>Try again</strong>.</p><p>Once meaning search is here, a switch above the results chooses <strong>Words and meaning</strong>, <strong>Words</strong> or <strong>Meaning</strong>. Meaning results come under <strong>Meaning</strong>, closest first, each labelled <strong>meaning · close</strong> or <strong>meaning · related</strong>, and the foot of the list says <strong>meaning runs on this computer</strong>.</p><h3 id="ask-how-to-do-something" tabindex="-1">Ask how to do something <a class="header-anchor" href="#ask-how-to-do-something" aria-label="Permalink to &quot;Ask how to do something&quot;">​</a></h3><p>Type a question, such as <code>how do I export?</code>, and under the list the mate answers under <strong>How do I</strong>: the steps, from the app&#39;s commands, this guide or its skills, and a button <strong>Run:</strong> with the command, and its key. When nothing on this computer answers, it says <strong>Nothing on this computer answers that.</strong> and offers the <strong>Nearest command</strong>. No model is used.</p><h2 id="capture-a-line-from-any-app" tabindex="-1">Capture a line from any app <a class="header-anchor" href="#capture-a-line-from-any-app" aria-label="Permalink to &quot;Capture a line from any app&quot;">​</a></h2><p>The capture window takes a line from wherever you are, a quote in a browser, a thought in another program, and makes it a card in the Writer&#39;s <strong>Ideas</strong> list, where it waits for a story.</p><h3 id="turn-on-the-key" tabindex="-1">Turn on the key <a class="header-anchor" href="#turn-on-the-key" aria-label="Permalink to &quot;Turn on the key&quot;">​</a></h3><p>The capture key works anywhere on the computer, so it is off until you turn it on. In <strong>Settings</strong>, open <strong>Hotkeys</strong>. Under <strong>Anywhere on this computer</strong>:</p><ul><li><strong>Turn on global keys</strong> turns on both keys that work outside Leathercase.</li><li><strong>Capture to Writer</strong> is <code>Ctrl+Shift+N</code> by default: it opens a small window over any app; what you type lands in the Writer&#39;s Ideas.</li><li><strong>Show Leathercase</strong> is <code>Ctrl+Shift+S</code> by default: it brings Leathercase forward from any app.</li></ul><p>Click a key to change it, then press the keys you want; changing a key turns global keys on. If another app holds the key, Settings says so in amber and pressing it does nothing; pick other keys. <strong>Turn off global keys</strong> lets both go, so other apps can have them. These keys belong to this computer and live in its preferences, not in your writing home.</p><p><img src="'+c+'" alt="Settings, Hotkeys, with Anywhere on this computer turned on and the two keys" width="880" height="377" loading="lazy"></p><h3 id="use-the-window" tabindex="-1">Use the window <a class="header-anchor" href="#use-the-window" aria-label="Permalink to &quot;Use the window&quot;">​</a></h3><p>Press the capture key in any app. A small window titled <strong>Capture to Writer</strong> opens over it, with the caret in its one field. Its top right corner names the writing home it will land in, followed by <strong>Ideas</strong> (the last home you were in).</p><ol><li>Type or paste. The placeholder says it: <strong>A line, a quote, a what-if. The first line becomes the card&#39;s title.</strong></li><li>If the home has stories, <strong>To</strong> chooses where it goes: <strong>Ideas, in the Writer</strong> (the default), or <strong>Loose on</strong> a story&#39;s <strong>beat board</strong>. The window remembers your last choice.</li><li>Press <code>Ctrl+Enter</code> or <strong>Save</strong>. The footer says <strong>Saved</strong> and the file it wrote, and the window closes.</li></ol><p><code>Esc</code> or <strong>Cancel</strong> closes it without saving. Before you type, the footer says <strong>The card lands in Ideas, where it waits for a board.</strong>; as you type, it shows the file the card will be.</p><p>The title is the first line of what you typed, with the quotation marks around it taken off and cut at a word near sixty characters. The whole text is the card. Captured to Ideas, it is a card note in the home&#39;s <code>Writer/</code> folder, tagged <code>writer/idea</code> and of the kind idea. Captured to a beat board, it is a loose card note in that story&#39;s <code>suite/Beats/</code> folder; see <a href="/guide/guide/beat-board">Beat board</a>. When you come back to Leathercase, the card is on the board.</p><p>If no writing home is open yet, the window says <strong>Open a writing home in Leathercase first.</strong></p>',35)),s(o,{name:"find-capture",caption:"The capture window: the footer names the card's file as you type, and Ctrl+Enter saves it to Ideas"}),e[3]||(e[3]=t('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/writer-board">The Writer Board</a></li><li><a href="/guide/guide/tags">Tags</a></li><li><a href="/guide/reference/keys">Keys and commands</a></li><li><a href="/guide/guide/mate">The mate</a></li></ul>',2))])}const _=a(p,[["render",m]]);export{T as __pageData,_ as default};
